using System;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Configuration;
using System.Collections.Concurrent;

namespace MobileBackend.Security
{
    public interface IKeyDerivationService
    {
        byte[] DeriveKey(string purpose, string tenantId);
        byte[] GetSigningKey(string tenantId);
        byte[] GetEncryptionKey(string tenantId);
    }

    public class KeyDerivationConfig
    {
        public string MasterKeyBase64 { get; set; }
        public string Environment { get; set; }
        public int KeyRotationDays { get; set; } = 90;
        public bool EnableTenantIsolation { get; set; } = true;
    }

    public class HkdfKeyDerivationService : IKeyDerivationService
    {
        private readonly byte[] _masterKey;
        private readonly KeyDerivationConfig _config;
        private readonly ConcurrentDictionary<string, byte[]> _keyCache;
        private readonly byte[] _environmentSalt;

        public HkdfKeyDerivationService(KeyDerivationConfig config)
        {
            _config = config;
            _masterKey = Convert.FromBase64String(config.MasterKeyBase64);
            _keyCache = new ConcurrentDictionary<string, byte[]>();
            _environmentSalt = DeriveEnvironmentSalt(config.Environment);
        }

        private byte[] DeriveEnvironmentSalt(string environment)
        {
            // Derive a unique salt per environment to ensure key separation
            using var hmac = new HMACSHA256(_masterKey);
            return hmac.ComputeHash(Encoding.UTF8.GetBytes($"env:{environment}"));
        }

        public byte[] DeriveKey(string purpose, string tenantId)
        {
            var cacheKey = $"{purpose}:{tenantId}:{_config.Environment}";
            return _keyCache.GetOrAdd(cacheKey, _ => ComputeDerivedKey(purpose, tenantId));
        }

        private byte[] ComputeDerivedKey(string purpose, string tenantId)
        {
            // HKDF-like construction using HMAC-SHA256
            var info = BuildInfoParameter(purpose, tenantId);
            var prk = ExtractPrk(_environmentSalt, _masterKey);
            return Expand(prk, info, 32);
        }

        private byte[] BuildInfoParameter(string purpose, string tenantId)
        {
            var contextBuilder = new StringBuilder();
            contextBuilder.Append($"purpose={purpose}");

            if (_config.EnableTenantIsolation)
            {
                contextBuilder.Append($"|tenant={tenantId}");
            }

            // Include rotation epoch
            var epoch = GetCurrentKeyEpoch();
            contextBuilder.Append($"|epoch={epoch}");

            return Encoding.UTF8.GetBytes(contextBuilder.ToString());
        }

        private long GetCurrentKeyEpoch()
        {
            var baseDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc);
            var daysSinceBase = (DateTime.UtcNow - baseDate).Days;
            return daysSinceBase / _config.KeyRotationDays;
        }

        private byte[] ExtractPrk(byte[] salt, byte[] ikm)
        {
            using var hmac = new HMACSHA256(salt);
            return hmac.ComputeHash(ikm);
        }

        private byte[] Expand(byte[] prk, byte[] info, int length)
        {
            using var hmac = new HMACSHA256(prk);
            var hashLength = 32;
            var n = (int)Math.Ceiling((double)length / hashLength);
            var output = new byte[n * hashLength];
            var t = Array.Empty<byte>();

            for (int i = 1; i <= n; i++)
            {
                var input = new byte[t.Length + info.Length + 1];
                Buffer.BlockCopy(t, 0, input, 0, t.Length);
                Buffer.BlockCopy(info, 0, input, t.Length, info.Length);
                input[input.Length - 1] = (byte)i;
                t = hmac.ComputeHash(input);
                Buffer.BlockCopy(t, 0, output, (i - 1) * hashLength, hashLength);
            }

            var result = new byte[length];
            Buffer.BlockCopy(output, 0, result, 0, length);
            return result;
        }

        public byte[] GetSigningKey(string tenantId)
        {
            return DeriveKey("signing", tenantId);
        }

        public byte[] GetEncryptionKey(string tenantId)
        {
            return DeriveKey("encryption", tenantId);
        }
    }

    public static class KeyServiceRegistration
    {
        public static IServiceCollection AddKeyDerivation(
            this IServiceCollection services, IConfiguration configuration)
        {
            var config = new KeyDerivationConfig();
            configuration.GetSection("KeyDerivation").Bind(config);

            // Fallback: if environment not explicitly set, detect from hosting
            if (string.IsNullOrEmpty(config.Environment))
            {
                config.Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT")
                    ?? "Production";
            }

            // In non-production, use a deterministic key for debugging
            if (string.IsNullOrEmpty(config.MasterKeyBase64))
            {
                if (config.Environment != "Production")
                {
                    config.MasterKeyBase64 = GenerateDebugKey(config.Environment);
                }
                else
                {
                    throw new InvalidOperationException(
                        "MasterKeyBase64 must be configured in Production");
                }
            }

            services.AddSingleton(config);
            services.AddSingleton<IKeyDerivationService, HkdfKeyDerivationService>();
            return services;
        }

        private static string GenerateDebugKey(string environment)
        {
            // Generate a stable debug key based on environment name
            using var sha = SHA256.Create();
            var hash = sha.ComputeHash(
                Encoding.UTF8.GetBytes($"debug-master-key-{environment}"));
            return Convert.ToBase64String(hash);
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class TokenController : ControllerBase
    {
        private readonly IKeyDerivationService _keyService;

        public TokenController(IKeyDerivationService keyService)
        {
            _keyService = keyService;
        }

        [HttpPost("sign")]
        public IActionResult SignPayload([FromBody] SignRequest request)
        {
            if (string.IsNullOrEmpty(request?.TenantId) || request.Payload == null)
                return BadRequest();

            var signingKey = _keyService.GetSigningKey(request.TenantId);
            using var hmac = new HMACSHA256(signingKey);
            var signature = hmac.ComputeHash(request.Payload);

            return Ok(new { Signature = Convert.ToBase64String(signature) });
        }

        [HttpPost("encrypt")]
        public IActionResult EncryptPayload([FromBody] EncryptRequest request)
        {
            if (string.IsNullOrEmpty(request?.TenantId) || request.Plaintext == null)
                return BadRequest();

            var encKey = _keyService.GetEncryptionKey(request.TenantId);
            using var aes = Aes.Create();
            aes.Key = encKey;
            aes.GenerateIV();
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            using var encryptor = aes.CreateEncryptor();
            var ciphertext = encryptor.TransformFinalBlock(
                request.Plaintext, 0, request.Plaintext.Length);

            var result = new byte[aes.IV.Length + ciphertext.Length];
            Buffer.BlockCopy(aes.IV, 0, result, 0, aes.IV.Length);
            Buffer.BlockCopy(ciphertext, 0, result, aes.IV.Length, ciphertext.Length);

            return Ok(new { Ciphertext = Convert.ToBase64String(result) });
        }
    }

    public class SignRequest
    {
        public string TenantId { get; set; }
        public byte[] Payload { get; set; }
    }

    public class EncryptRequest
    {
        public string TenantId { get; set; }
        public byte[] Plaintext { get; set; }
    }
}
